/***  app\tooltip  ***/

$(function() {
  var gravity;
  gravity = {
    'top': 's',
    'top-left': 'sw',
    'top-right': 'se'
  };
  return Ember.String.w('top top-left top-right').forEach(function(direction) {
    return $(".acti-tooltip-" + direction).tipsy({
      gravity: gravity[direction],
      fade: true
    });
  });
});


